def find_triangle_volume(prism):
   volume = 0
   for row in prism:
       for col in row:
           volume += col
   return volume

def find_sequences(sequence):
   sequence = sequence.lower()
   sequences = []
   for char in sequence:
       if char == '_':
           sequences.append(char)
   return sequences

